BEGIN;
CREATE TABLE visit_report_templates (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),
 key text NOT NULL,version integer NOT NULL DEFAULT 1,definition jsonb NOT NULL,created_by uuid REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,key,version)
);
ALTER TABLE fleet_trip_reports ADD COLUMN template_snapshot jsonb;
ALTER TABLE fleet_trip_reports ADD COLUMN template_version integer;
ALTER TABLE fleet_trip_reports ADD COLUMN report_version integer NOT NULL DEFAULT 0;
ALTER TABLE fleet_trip_reports ADD COLUMN structured_content jsonb NOT NULL DEFAULT '{}';
ALTER TABLE fleet_trip_reports ADD COLUMN report_property_id uuid REFERENCES properties(id);
CREATE TABLE visit_report_answers (
 id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES fleet_trip_reports(id),question_id text NOT NULL,
 instance text NOT NULL DEFAULT 'default',location text NOT NULL DEFAULT 'Property-wide',notes text NOT NULL DEFAULT '',
 rating integer CHECK(rating BETWEEN 1 AND 5),not_applicable boolean NOT NULL DEFAULT false,
 task_id uuid REFERENCES tasks(id),task_plan jsonb NOT NULL DEFAULT '{"kind":"none"}',removed_at timestamptz,
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX visit_answer_question_instance ON visit_report_answers(report_id,question_id,instance) WHERE removed_at IS NULL;
CREATE TABLE visit_report_photos (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),answer_id uuid NOT NULL REFERENCES visit_report_answers(id),
 storage_path text UNIQUE NOT NULL,name text NOT NULL,content_type text NOT NULL,size integer NOT NULL CHECK(size>0 AND size<=10485760),
 state text NOT NULL DEFAULT 'uploading' CHECK(state IN ('uploading','ready','removed')),
 actor_id uuid NOT NULL REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE visit_report_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES fleet_trip_reports(id),
 actor_id uuid NOT NULL REFERENCES profiles(id),kind text NOT NULL,before_value jsonb,after_value jsonb,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER visit_report_event_immutable BEFORE UPDATE OR DELETE ON visit_report_events FOR EACH ROW EXECUTE FUNCTION task_append_only();
CREATE TABLE visit_report_acknowledgements (
 report_id uuid NOT NULL REFERENCES fleet_trip_reports(id),profile_id uuid NOT NULL REFERENCES profiles(id),
 report_version integer NOT NULL,acknowledged_at timestamptz,assigned_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(report_id,profile_id)
);
CREATE FUNCTION protect_report_template() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.template_snapshot IS NOT NULL AND (NEW.template_snapshot,NEW.template_version,NEW.report_property_id) IS DISTINCT FROM (OLD.template_snapshot,OLD.template_version,OLD.report_property_id) THEN RAISE EXCEPTION 'Report template and property are fixed after selection'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER report_template_fixed BEFORE UPDATE ON fleet_trip_reports FOR EACH ROW EXECUTE FUNCTION protect_report_template();
CREATE TRIGGER report_template_version_immutable BEFORE UPDATE OR DELETE ON visit_report_templates FOR EACH ROW EXECUTE FUNCTION task_append_only();
ALTER TABLE visit_report_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE visit_report_answers ENABLE ROW LEVEL SECURITY;
ALTER TABLE visit_report_photos ENABLE ROW LEVEL SECURITY;
ALTER TABLE visit_report_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE visit_report_acknowledgements ENABLE ROW LEVEL SECURITY;
CREATE INDEX visit_report_event_page ON visit_report_events(report_id,created_at);
CREATE INDEX visit_report_photo_answer ON visit_report_photos(answer_id,state);

INSERT INTO visit_report_templates(org_id,key,definition) SELECT id,'styling','{"key": "styling", "name": "Stylist & Interior Design", "visitTypes": ["Routine Styling Audit", "Pre-season Setup", "Special Project"], "sections": [{"id": "section-1", "title": "Public & Main Areas"}, {"id": "section-2", "title": "Guest Rooms & Suites"}, {"id": "section-3", "title": "Tea, Coffee & Minibar Stations"}, {"id": "section-4", "title": "Bathroom Aesthetics"}, {"id": "section-5", "title": "Outdoor & Pool Areas"}], "questions": [{"id": "q1", "sectionId": "section-1", "label": "Lighting & Ambience", "guidance": "Warm light only/no bright lights, lampshades straight with seams to the back", "kind": "inspection"}, {"id": "q2", "sectionId": "section-1", "label": "Soft Furnishings & Rugs", "guidance": "Scatter cushions with zippers down, rugs laid flat with fringes removed", "kind": "inspection"}, {"id": "q3", "sectionId": "section-1", "label": "Decor & Shelving", "guidance": "Books arranged large to small, clutter-free surfaces, candles cut down and bug-free", "kind": "inspection"}, {"id": "q4", "sectionId": "section-1", "label": "Floral & Greenery", "guidance": "Freshness of floral arrangements, water replaced daily", "kind": "inspection"}, {"id": "q5", "sectionId": "section-2", "label": "Room Ambience & Signature Touches", "guidance": "Presence of Taru Villas signature fragrance, leatherbound coffee table books", "kind": "inspection"}, {"id": "q6", "sectionId": "section-2", "label": "Bed Styling", "guidance": "Crisp 350 TC white linen, exactly 4 pillows [2 firm, 2 soft], 2 throw cushions centered, bed throws placed for arrival", "kind": "inspection"}, {"id": "q7", "sectionId": "section-2", "label": "Wardrobe & Accessories", "guidance": "Flip-flops and hairdryers presented neatly in designated fabric pouches", "kind": "inspection"}, {"id": "q8", "sectionId": "section-2", "label": "Lighting", "guidance": "Appropriate warm lighting, bedside lamps straight with seams facing the back", 